const attendance = $('Read Attendance Data').all();
const employees = $('Read Employee Master').all();

const currentMonth = new Date().getMonth();
const currentYear = new Date().getFullYear();

// Group attendance by employee
const empMap = {};
for (const emp of employees) {
  const id = emp.json.employee_id;
  empMap[id] = {
    ...emp.json,
    days_present: 0,
    days_absent: 0,
    days_late: 0,
    overtime_hours: 0
  };
}

for (const att of attendance) {
  const d = new Date(att.json.date);
  if (d.getMonth() !== currentMonth || d.getFullYear() !== currentYear) continue;
  const id = att.json.employee_id;
  if (!empMap[id]) continue;
  if (att.json.status === 'present' || att.json.status === 'hadir') empMap[id].days_present++;
  else if (att.json.status === 'absent' || att.json.status === 'absen') empMap[id].days_absent++;
  if (att.json.late === 'yes' || att.json.late === 'ya') empMap[id].days_late++;
  empMap[id].overtime_hours += Number(att.json.overtime_hours || 0);
}

const results = Object.values(empMap).map(emp => {
  const gajiPokok = Number(emp.gaji_pokok || 0);
  const tunjangan = Number(emp.tunjangan || 0);
  const potAbsen = emp.days_absent * (gajiPokok / 22);
  const lembur = emp.overtime_hours * (gajiPokok / 173);
  const gajiKotor = gajiPokok + tunjangan - potAbsen + lembur;
  // BPJS Kesehatan: 1% employee
  const bpjsKes = Math.round(gajiKotor * 0.01);
  // BPJS Ketenagakerjaan JHT: 2% employee
  const bpjsTK = Math.round(gajiKotor * 0.02);
  // PPh 21 simplified (assumes progressive)
  let pph21 = 0;
  const gajiTahunan = gajiKotor * 12;
  const ptkp = 54000000; // PTKP TK/0
  const pkp = Math.max(0, gajiTahunan - ptkp);
  if (pkp <= 60000000) pph21 = pkp * 0.05;
  else if (pkp <= 250000000) pph21 = 3000000 + (pkp - 60000000) * 0.15;
  else if (pkp <= 500000000) pph21 = 31500000 + (pkp - 250000000) * 0.25;
  else pph21 = 93750000 + (pkp - 500000000) * 0.30;
  pph21 = Math.round(pph21 / 12);
  const gajiNetto = Math.round(gajiKotor - bpjsKes - bpjsTK - pph21);
  return {
    employee_id: emp.employee_id,
    nama: emp.nama,
    jabatan: emp.jabatan || '-',
    gaji_pokok: gajiPokok,
    tunjangan: tunjangan,
    hari_hadir: emp.days_present,
    hari_absen: emp.days_absent,
    hari_terlambat: emp.days_late,
    jam_lembur: emp.overtime_hours,
    potongan_absen: Math.round(potAbsen),
    lembur: Math.round(lembur),
    gaji_kotor: Math.round(gajiKotor),
    bpjs_kesehatan: bpjsKes,
    bpjs_ketenagakerjaan: bpjsTK,
    pph21: pph21,
    gaji_netto: gajiNetto,
    bank_account: emp.no_rekening || '-',
    bank_name: emp.bank || 'BCA'
  };
});

return results.map(r => ({json: r}));

